-- Omega Amplify initial multi-tenant schema. Review in staging before applying.
create extension if not exists pgcrypto;
create table public.organisations (id uuid primary key default gen_random_uuid(), name text not null, created_at timestamptz not null default now());
create table public.memberships (organisation_id uuid not null references public.organisations(id) on delete cascade, user_id uuid not null references auth.users(id) on delete cascade, role text not null check(role in ('owner','manager','staff','client')), primary key(organisation_id,user_id));
create table public.services (id uuid primary key default gen_random_uuid(), organisation_id uuid not null references public.organisations(id) on delete cascade, type text not null check(type in ('paid','organic','leads_only','leads_closing')), status text not null default 'active' check(status in ('active','paused','cancelled')), created_at timestamptz not null default now());
create table public.projects (id uuid primary key default gen_random_uuid(), organisation_id uuid not null references public.organisations(id) on delete cascade, service_id uuid references public.services(id) on delete set null, name text not null, status text not null default 'planned', created_at timestamptz not null default now());
create table public.leads (id uuid primary key default gen_random_uuid(), organisation_id uuid not null references public.organisations(id) on delete cascade, project_id uuid references public.projects(id) on delete set null, name text not null, stage text not null default 'new', email text, phone text, created_at timestamptz not null default now());
create table public.deliverables (id uuid primary key default gen_random_uuid(), organisation_id uuid not null references public.organisations(id) on delete cascade, project_id uuid references public.projects(id) on delete set null, title text not null, description text, status text not null default 'draft' check(status in ('draft','submitted','approved','changes_requested','published')), due_at timestamptz, created_at timestamptz not null default now());
create table public.tasks (id uuid primary key default gen_random_uuid(), organisation_id uuid not null references public.organisations(id) on delete cascade, project_id uuid references public.projects(id) on delete set null, assignee_id uuid references auth.users(id) on delete set null, title text not null, status text not null default 'todo', due_at timestamptz, created_at timestamptz not null default now());
create table public.messages (id uuid primary key default gen_random_uuid(), organisation_id uuid not null references public.organisations(id) on delete cascade, sender_id uuid not null references auth.users(id), body text not null check(length(body) between 1 and 10000), created_at timestamptz not null default now());
create table public.invoices (id uuid primary key default gen_random_uuid(), organisation_id uuid not null references public.organisations(id) on delete cascade, external_invoice_id text unique, amount_cents bigint not null check(amount_cents>=0), currency text not null default 'AUD', status text not null default 'draft', created_at timestamptz not null default now());
create table public.audit_events (id uuid primary key default gen_random_uuid(), organisation_id uuid not null references public.organisations(id) on delete cascade, actor_id uuid references auth.users(id), event_type text not null, entity_id uuid, created_at timestamptz not null default now());
create index on public.memberships(user_id,organisation_id);
create index on public.leads(organisation_id,created_at desc);
create index on public.tasks(organisation_id,status);
create index on public.deliverables(organisation_id,status);
create index on public.messages(organisation_id,created_at desc);
create or replace function public.has_org_access(org uuid) returns boolean language sql stable security definer set search_path='' as $$select exists(select 1 from public.memberships m where m.organisation_id=org and m.user_id=(select auth.uid()))$$;
create or replace function public.has_org_staff_access(org uuid) returns boolean language sql stable security definer set search_path='' as $$select exists(select 1 from public.memberships m where m.organisation_id=org and m.user_id=(select auth.uid()) and m.role in ('owner','manager','staff'))$$;
revoke all on function public.has_org_access(uuid) from public;
revoke all on function public.has_org_staff_access(uuid) from public;
grant execute on function public.has_org_access(uuid),public.has_org_staff_access(uuid) to authenticated;
alter table public.organisations enable row level security;
alter table public.memberships enable row level security;
alter table public.services enable row level security;
alter table public.projects enable row level security;
alter table public.leads enable row level security;
alter table public.deliverables enable row level security;
alter table public.tasks enable row level security;
alter table public.messages enable row level security;
alter table public.invoices enable row level security;
alter table public.audit_events enable row level security;
create policy "members read organisations" on public.organisations for select to authenticated using(public.has_org_access(id));
create policy "members read memberships" on public.memberships for select to authenticated using(public.has_org_access(organisation_id));
create policy "members read services" on public.services for select to authenticated using(public.has_org_access(organisation_id));
create policy "staff manage services" on public.services for all to authenticated using(public.has_org_staff_access(organisation_id)) with check(public.has_org_staff_access(organisation_id));
create policy "members read projects" on public.projects for select to authenticated using(public.has_org_access(organisation_id));
create policy "staff manage projects" on public.projects for all to authenticated using(public.has_org_staff_access(organisation_id)) with check(public.has_org_staff_access(organisation_id));
create policy "members read leads" on public.leads for select to authenticated using(public.has_org_access(organisation_id));
create policy "staff manage leads" on public.leads for all to authenticated using(public.has_org_staff_access(organisation_id)) with check(public.has_org_staff_access(organisation_id));
create policy "members read deliverables" on public.deliverables for select to authenticated using(public.has_org_access(organisation_id));
create policy "staff manage deliverables" on public.deliverables for all to authenticated using(public.has_org_staff_access(organisation_id)) with check(public.has_org_staff_access(organisation_id));
create policy "clients review submitted deliverables" on public.deliverables for update to authenticated using(public.has_org_access(organisation_id) and status in ('submitted','changes_requested')) with check(public.has_org_access(organisation_id) and status in ('approved','changes_requested'));
create policy "members read tasks" on public.tasks for select to authenticated using(public.has_org_access(organisation_id));
create policy "staff manage tasks" on public.tasks for all to authenticated using(public.has_org_staff_access(organisation_id)) with check(public.has_org_staff_access(organisation_id));
create policy "members read messages" on public.messages for select to authenticated using(public.has_org_access(organisation_id));
create policy "members send messages" on public.messages for insert to authenticated with check(public.has_org_access(organisation_id) and sender_id=(select auth.uid()));
create policy "members read invoices" on public.invoices for select to authenticated using(public.has_org_access(organisation_id));
create policy "members read audit events" on public.audit_events for select to authenticated using(public.has_org_staff_access(organisation_id));
-- No direct client writes to invoices, memberships or audit events. Use trusted server functions.
-- IMPORTANT: Cross-organisation FK validation and immutable field protection require additional triggers/RPCs before production.
